const ic=(key)=>`<svg class="icon-svg" viewBox="0 0 24 24" aria-hidden="true">${ICONS[key]??ICONS.help}</svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=t=>t?new Date(t).toLocaleString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const time=t=>t?new Date(t).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
const tag=(t,type='neutral')=>`<span class="tag ${type}">${esc(t)}</span>`;
const btn=(label,action,type='',attrs='')=>`<button type="button" class="button ${type}" data-action="${action}" ${attrs}>${label}</button>`;
const brand=()=>`<div class="brand" aria-label="Hondas Maxvel, tecnologia Horizon"><img class="brand-icon" src="./assets/maxvel-icon.svg" alt="" width="43" height="43"><span class="brand-copy"><span class="maxvel-word">HONDAS <strong>MAXVEL</strong><small>GESTÃO DE RONDAS</small></span><span class="brand-by">por <b>HORIZON</b></span></span></div>`;
const persisted=loadState();
let sessions=Array.isArray(persisted?.sessions)?persisted.sessions:[];
let user=null,screen='landing',view='overview',presentation=false,guideStage=0,presentationName='Lucas Ferreira',mode='simulation',session=null;
let priorSimulation=null;
let nativeTracking=false,locationFix=null,deviceWatch=null,movement=null,liveMaps=[],toastTimer=null,renderNumber=0,justRendered=0,tabFilter='all',contextWarning='';
const sessionList=()=>[...sessions].sort((a,b)=>b.startedAt-a.startedAt);
const current=()=>session;
const recentNotification=()=>sessionList().flatMap(s=>(s.notifications??[]).map(n=>({...n,session:s}))).sort((a,b)=>b.at-a.at);
const recentIncidents=()=>sessionList().flatMap(s=>(s.incidents??[]).map(i=>({...i,session:s}))).sort((a,b)=>b.at-a.at);
function persist(){const ok=saveState({sessions,activeSessionId:session?.status==='active'&&mode==='real'?session.id:null,activeUser:session?.status==='active'&&mode==='real'?user:null});if(!ok)notify('Não foi possível gravar no navegador. Confira o espaço disponível.');}
function save(){if(session){const idx=sessions.findIndex(s=>s.id===session.id);if(idx>=0)sessions[idx]=session;else sessions.unshift(session);}persist()}
function notify(message){toast.textContent=message;toast.classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('toast-visible'),4900)}
function destroyMaps(){for(const m of liveMaps)m?.destroy();liveMaps=[]}
function registerMap(id,route,sessionRef=null,position=null,compact=false){const el=document.getElementById(id);if(!el)return;liveMaps.push(new PatrolMap(el,{route,session:sessionRef,position,compact,interactive:true}))}
function render(){destroyMaps();renderNumber++;modal.close?.();
 if(screen==='landing')root.innerHTML=landing();
 else if(screen==='presentation')root.innerHTML=appShell();
 else root.innerHTML=appShell();
 attachMaps();justRendered=Date.now();
}
function attachMaps(){
 if(screen==='landing')registerMap('hero-map',DEMO_ROUTE,null,DEMO_ROUTE.base,true);
 if(screen==='presentation'||screen==='dashboard'){
  if(view==='overview'||view==='rondas')registerMap('ops-map',session?.route??DEMO_ROUTE,session,locationFix??DEMO_ROUTE.base,false);
  if(view==='minha-ronda')registerMap('mobile-map',session?.route??DEMO_ROUTE,session,locationFix??DEMO_ROUTE.base,true);
 }
}
function landing(){
 const examples=[['shield','Acompanhamento contínuo','Histórico de etapas e condições da ronda'],['map','Cartografia contextual','Pontos, raio e progresso sobre ruas reais'],['bell','Desvios documentados','Justificativa vinculada à supervisão'],['clipboard','Histórico consultável','Eventos e registros em ordem cronológica']];
 return `<div class="hero product-home"><div class="hero-container"><header class="topnav">${brand()}<nav class="nav-actions" aria-label="Acesso rápido">${btn(ic('help')+' Guia da plataforma','guide','','')} ${btn('Entrar no sistema '+ic('arrow'),'login','primary small')}</nav></header><main id="main"><section class="product-hero"><div class="product-hero-copy"><div class="eyebrow">${ic('shield')} HONDAS MAXVEL · OPERAÇÕES EM CAMPO</div><h1>Uma visão completa<br>de cada <span>ronda.</span></h1><p>Acompanhe o trabalho em campo e a supervisão em um só ambiente. Pontos, trajetos, permanência e ocorrências apresentados com clareza, do celular ao computador.</p><div class="hero-buttons">${btn('Experimentar o aplicativo '+ic('arrow'),'presentation-intro','primary')}${btn('Acessar minha área','login')}</div><div class="product-benefits"><span>${ic('checkcircle')} Passo a passo para o colaborador</span><span>${ic('checkcircle')} Visão da supervisão</span><span>${ic('checkcircle')} Registros com contexto</span></div><p class="product-fineprint">${ic('help')} Ambiente de avaliação: trajeto, pessoas e alertas ilustrativos. A cartografia é real quando online.</p></div><div class="product-showcase"><div class="showcase-main"><div class="showcase-toolbar"><div class="showcase-title">${ic('map')} <strong>Central de acompanhamento</strong><small>Prévia funcional do mapa</small></div><span class="showcase-status"><i></i> Visualização de rota</span></div><div id="hero-map" class="showcase-map"></div><div class="showcase-map-badge">${ic('pin')} Rota Centro · Divinópolis <span>4 pontos · raio 25 m</span></div><div class="showcase-overlay-stats"><div><small>Próxima verificação</small><strong>Portaria principal</strong></div><span>${ic('crosshair')} 25 m</span></div></div><div class="showcase-detail-grid"><div class="showcase-detail"><span class="showcase-detail-icon">${ic('clock')}</span><span><small>Permanência por ponto</small><strong>30 segundos contínuos</strong></span></div><div class="showcase-detail"><span class="showcase-detail-icon">${ic('bell')}</span><span><small>Desvios de percurso</small><strong>Justificativa e análise</strong></span></div></div><div class="showcase-disclaimer">Mapa OpenStreetMap · cenário operacional fictício</div></div></section><section class="product-capabilities"><div class="capabilities-intro"><div class="eyebrow">UMA PLATAFORMA · QUATRO FRENTES</div><h2>Feita para acompanhar a operação, não para complicá-la.</h2><p>O mesmo processo apresentado de forma específica para quem executa e para quem supervisiona.</p></div><div class="capability-grid">${examples.map(([ico,title,desc],i)=>`<article class="capability"><span class="capability-index">0${i+1}</span><span class="capability-icon">${ic(ico)}</span><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div></section><section class="product-endcap"><div><div class="eyebrow">VEJA O FLUXO COMPLETO</div><h2>Do primeiro ponto ao relatório final.</h2><p>Explore as telas reais da experiência proposta para ronda e supervisão, com cenário operacional interativo.</p></div>${btn('Experimentar o aplicativo '+ic('arrow'),'presentation-intro','primary')}</section></main><footer class="hero-foot"><span>Desenvolvido por Horizon | Daniel N. Xavier</span><a href="#" data-action="privacy">Privacidade e requisitos técnicos</a></footer></div></div>`;
}
const allNav={ronda:[['minha-ronda','Minha ronda','compass'],['registros','Meus registros','folder'],['ocorrencias','Ocorrências','alert']],supervisor:[['overview','Visão geral','chart'],['rondas','Rondas','map'],['notificacoes','Notificações','bell'],['ocorrencias','Ocorrências','alert'],['relatorios','Relatórios','clipboard']],gestor:[['overview','Visão geral','chart'],['rondas','Rondas','map'],['notificacoes','Notificações','bell'],['ocorrencias','Ocorrências','alert'],['equipe','Equipe','users'],['relatorios','Relatórios','clipboard']],admin:[['overview','Visão geral','chart'],['rondas','Rondas','map'],['notificacoes','Notificações','bell'],['ocorrencias','Ocorrências','alert'],['equipe','Equipe','users'],['relatorios','Relatórios','clipboard'],['configuracoes','Configurações','settings']]};
const mobileNavFor=role=>role==='ronda'?[['minha-ronda','Minha ronda','compass'],['ocorrencias','Ocorrências','alert'],['registros','Histórico','folder']]:[['overview','Operação','chart'],['rondas','Mapa','map'],['notificacoes','Alertas','bell'],['relatorios','Registros','clipboard']];
const roleName={ronda:'Ronda',supervisor:'Supervisão',gestor:'Gestão',admin:'Administração'};
function simRoleBar(){
 if(!presentation)return '';
 const roles=[['ronda','Ronda','compass'],['supervisor','Supervisão','eye'],['gestor','Gestão','chart'],['admin','Admin','settings']];
 const currentRole=user?.role??'ronda',point=session?.status==='active'?session.index+1:0,total=session?.route?.points.length??4;
 return `<div class="simulation-rolebar" aria-label="Ambiente interativo do aplicativo"><div class="simulation-caption"><span class="simulation-signal"></span><strong>Aplicativo em simulação</strong><small>Dados locais · sem rastreamento real</small></div><nav class="simulation-roles" aria-label="Alternar perfis do aplicativo">${roles.map(([role,label,icon])=>`<button type="button" data-action="sim-role" data-role="${role}" aria-pressed="${currentRole===role}" class="${currentRole===role?'selected':''}">${ic(icon)}<span>${label}</span></button>`).join('')}</nav><div class="simulation-actions"><span class="simulation-progress">${session?`Ponto ${Math.min(point,total)} / ${total}`:'Pronto para iniciar'}</span><button type="button" data-action="end-presentation" aria-label="Sair da simulação" title="Sair da simulação">${ic('close')}<span> Sair</span></button></div></div>`;
}
function beginSimulation(name,autoStart=false,startRole='ronda'){
 if(!presentation)priorSimulation={user:user?{...user}:null,view,session,mode};
 if(session?.status==='active'&&mode==='real'){notify('Finalize a ronda com GPS antes de explorar a simulação.');return;}
 stopLocation();presentation=true;screen='dashboard';mode='simulation';
 presentationName=(name||presentationName).slice(0,60);
 user={name:presentationName,role:startRole};
 view=startRole==='ronda'?'minha-ronda':'overview';
 session=autoStart?createSession(presentationName,DEMO_ROUTE,Date.now(),'simulation'):null;
 locationFix={...DEMO_ROUTE.base,accuracy:5,at:Date.now()};
 movement=null;
 if(session)save();
 render();window.scrollTo({top:0,behavior:'instant'});
}
function endSimulation(){
 if(!presentation)return;
 stopLocation();movement=null;
 const prev=priorSimulation;
 presentation=false;priorSimulation=null;
 screen=prev?.user?'dashboard':'landing';user=prev?.user??null;
 view=prev?.view??'overview';session=prev?.session??null;mode=prev?.mode??'simulation';
 locationFix=null;render();window.scrollTo({top:0,behavior:'instant'});
}
function simulationIntro(){
 showDialog(`<div class="sim-onboarding"><div class="eyebrow">HONDAS MAXVEL · HORIZON</div><h2>Experimente o aplicativo real</h2><p>Você usará as próprias telas do sistema, com o mapa e os registros funcionando em um cenário fictício.</p><div class="sim-intro-steps"><div>${ic('compass')}<span><strong>Execute a ronda</strong>Inicie, desloque-se e valide os pontos.</span></div><div>${ic('alert')}<span><strong>Teste uma saída da rota</strong>Justifique e veja o bloqueio da etapa.</span></div><div>${ic('eye')}<span><strong>Alterne para Supervisão</strong>Confira alertas, mapa e registros no mesmo aplicativo.</span></div></div><label class="field">Nome de exemplo<input id="presentation-name" maxlength="60" value="${esc(presentationName)}"></label><div class="sim-onboarding-actions">${btn('Entrar no aplicativo '+ic('arrow'),'launch-presentation','primary full')}${btn('Ler instruções detalhadas','guide','full')}</div><p class="map-caption">Sem GPS real e sem envio remoto. As regras de raio e permanência continuam valendo no cenário.</p></div>`);
}

function pageTitle(title,sub,extra=''){return `<div class="page-title"><div><div class="eyebrow">MAXVEL · ${esc(roleName[user.role])}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function appShell(){const entries=allNav[user.role],mobileEntries=mobileNavFor(user.role);let valid=entries.find(x=>x[0]===view);if(!valid){view=entries[0][0];valid=entries[0];}
 return `<div class="dashboard ${presentation?'simulation-mode':''}"><div class="app-shell"><aside class="sidebar">${brand()}<span class="side-caption">ÁREA DE TRABALHO</span><nav class="side-links" aria-label="Navegação principal">${entries.map(([key,title,ico])=>`<button data-view="${key}" class="side-link ${view===key?'active':''}">${ic(ico)}${title}${key==='notificacoes'&&recentNotification().filter(x=>!x.seenAt).length?`<span class="count">${recentNotification().filter(x=>!x.seenAt).length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom">${tag('Dados demonstrativos','neutral')}<p style="font-size:11px;margin-top:12px">Alertas locais, sem servidor conectado.</p><button class="foot-link" data-action="privacy">Privacidade e dados</button><button class="foot-link" data-action="guide">Guia completo</button><button class="foot-link" data-action="logout">Sair do perfil</button><p style="font-size:10px;margin-top:12px">Desenvolvido por Horizon</p></div></aside><div class="shell-main"><header class="app-header">${brand()}<div class="eyebrow desktop-only">OPERAÇÃO · CENÁRIO DEMONSTRATIVO</div><div class="header-actions"><button class="help-toggle" data-action="guide" aria-label="Abrir ajuda e instruções">${ic('help')}<span class="desktop-only">Ajuda</span></button><button type="button" class="user-pill user-profile-button" data-action="profile-menu" aria-label="Abrir perfil e opções"><span class="avatar">${esc(user.name.slice(0,1).toUpperCase())}</span><span><strong>${esc(user.name)}</strong><small>${roleName[user.role]}</small></span>${ic("settings")}</button><button class="button small desktop-only" data-action="logout">Sair</button></div></header>${simRoleBar()}<main id="main" class="app-content ${view==='minha-ronda'?'ronda-page':''}">${viewContent()}</main><nav class="mobile-nav mobile-only" style="--nav-items:${mobileEntries.length}" aria-label="Navegação móvel">${mobileEntries.map(([key,title,ico])=>`<button class="${view===key?'active':''}" data-view="${key}">${ic(ico)}<span>${title}</span></button>`).join('')}</nav><footer class="footer-app">Ambiente de avaliação · dados locais · Desenvolvido por Horizon</footer></div></div></div>`}
function viewContent(){switch(view){case 'minha-ronda':return pageTitle('Minha ronda','Veja a situação atual e execute o próximo passo.',btn(ic('help')+' Instruções','guide','small'))+phoneContent();case 'registros':return personalRecords();case 'overview':return overview();case 'rondas':return rondas();case 'notificacoes':return notificationsView();case 'ocorrencias':return occurrences();case 'equipe':return team();case 'relatorios':return reports();case 'configuracoes':return settings();default:return overview();}}
function kpiCards(){const all=sessionList(),alerts=recentNotification(),inc=recentIncidents();const rows=[['Rondas registradas',all.length,'Sessões criadas no navegador'],['Concluídas',all.filter(s=>s.status==='completed').length,'Retorno à base confirmado'],['Desvios',all.reduce((n,s)=>n+s.deviations.length,0),'Eventos com justificativa'],['Ocorrências',inc.length,'Solicitações de análise']];return `<div class="grid-kpis">${rows.map(([label,n,detail])=>`<div class="card kpi"><small>${label}</small><strong>${String(n).padStart(2,'0')}</strong><em>${detail}</em></div>`).join('')}</div>`;}
function overview(){
 const all=sessionList(),alerts=recentNotification(),open=alerts.filter(x=>!x.seenAt),inc=recentIncidents(),finished=all.filter(s=>s.status==='completed'),active=all.filter(s=>s.status==='active');
 const metricRows=[
  {icon:'compass',name:'Rondas registradas',value:all.length,detail:`${active.length} em andamento neste navegador`,tone:'blue'},
  {icon:'checkcircle',name:'Rondas finalizadas',value:finished.length,detail:'Com retorno à base registrado',tone:'green'},
  {icon:'pin',name:'Pontos verificados',value:all.reduce((n,s)=>n+(s.checkpoints??[]).filter(x=>x.completedAt).length,0),detail:'Permanência e sequência documentadas',tone:'blue'},
  {icon:'alert',name:'Alertas para análise',value:open.length,detail:`${inc.length} ocorrências no histórico`,tone:open.length?'red':'neutral'}
 ];
 const activeSession=active[0]??all[0],trail=activeSession?.timeline??[];
 return `<div class="operations-page">${pageTitle('Central de operações','Acompanhe rotas, pontos, justificativas e ocorrências no mesmo painel.',btn(ic('print')+' Imprimir relatório','print','small'))}<div class="ops-topline"><div><span class="ops-live-dot"></span><strong>Visão da operação</strong><span>Dados deste ambiente de avaliação</span></div><div class="ops-topline-right">${ic('clock')} <span>${new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'})}</span> ${tag('Cenário local','neutral')}</div></div>${all.length===0?`<div class="ops-scenario-banner"><div class="ops-scenario-message"><span class="ops-scenario-symbol">${ic('compass')}</span><div><strong>Quer ver a operação funcionando?</strong><p>Execute uma ronda ilustrativa: o mapa se movimenta, os pontos são validados e os alertas aparecem na supervisão.</p></div></div>${btn('Executar cenário completo '+ic('arrow'),'launch-scenario','primary')}</div>`:`<div class="ops-scenario-shortcut"><span>${ic('eye')} Cenário disponível para apresentação</span>${btn('Abrir simulação integrada','launch-scenario','small')}</div>`}<div class="ops-metrics">${metricRows.map(m=>`<article class="ops-metric tone-${m.tone}"><div class="ops-metric-top"><span class="ops-metric-icon">${ic(m.icon)}</span><span class="ops-metric-arrow">${ic('arrow')}</span></div><strong>${String(m.value).padStart(2,'0')}</strong><h3>${m.name}</h3><p>${m.detail}</p></article>`).join('')}</div><div class="ops-workspace"><section class="ops-map-card"><div class="ops-panel-heading"><div><div class="eyebrow">ACOMPANHAMENTO GEOGRÁFICO</div><h2>${ic('map')} Mapa de rondas</h2><p>Traçado ilustrativo sobre cartografia real, quando online</p></div><div class="ops-map-actions">${tag('4 pontos planejados','neutral')}${btn(ic('crosshair')+' Enquadrar','center-maps','small')}</div></div><div class="ops-map-stage"><div id="ops-map" class="map-container large"></div><div class="ops-map-corner"><strong>${ic('shield')} Rota Centro · Perímetro</strong><span>Área de verificação · 25 m</span></div></div><div class="ops-map-legend">${legend()}<span class="ops-map-note">Pontos e trajeto de demonstração</span></div></section><aside class="ops-activity"><div class="ops-panel-heading"><div><div class="eyebrow">FILA DE ATENÇÃO</div><h2>${ic('bell')} Alertas e justificativas</h2><p>Eventos registrados neste navegador</p></div>${tag(`${open.length} pendente(s)`,open.length?'red':'green')}</div><div class="ops-alert-list">${alerts.slice(0,6).map(notificationRow).join('')||`<div class="ops-empty"><span>${ic('shield')}</span><strong>Operação sem alertas pendentes</strong><p>Ao identificar um desvio, ele aparecerá aqui junto com o contexto para análise.</p></div>`}</div><div class="ops-help">${ic('help')} <span>Falhas de GPS não devem ser tratadas automaticamente como irregularidades.</span></div></aside></div><div class="ops-bottom-grid"><section class="card ops-recent"><div class="card-title"><div><div class="eyebrow">REGISTROS RECENTES</div><h2>Histórico de rondas</h2></div>${btn('Ver todas '+ic('arrow'),'nav-rondas','small')}</div>${tablePatrols(all.slice(0,5))}</section><aside class="card ops-progress"><div class="eyebrow">LINHA DO TEMPO</div><h2>Última atividade</h2><p>${activeSession?`Referente a ${esc(activeSession.name)} · ${esc(activeSession.route.name)}`:'Inicie uma ronda para acompanhar os registros.'}</p><div class="ops-timeline">${trail.slice(0,5).map(t=>`<div class="ops-timeline-item"><i></i><div><strong>${esc(t.label)}</strong><small>${time(t.at)}</small></div></div>`).join('')||'<div class="empty">Aguardando início da primeira ronda.</div>'}</div></aside></div><div class="ops-footer-note">${ic('help')} Protótipo operacional: os registros são locais e não chegam a um supervisor real. A implantação requer servidor e autenticação.</div></div>`;
}
function tablePatrols(rows){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Responsável</th><th>Rota</th><th>Progresso</th><th>Situação</th><th>Início</th><th>Detalhes</th></tr></thead><tbody>${rows.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.route.name)}</td><td>${s.index} / ${s.route.points.length} pontos</td><td>${tag(s.status==='completed'?'Concluída':'Em andamento',s.status==='completed'?'green':'orange')}</td><td>${fmt(s.startedAt)}</td><td><button data-action="session-detail" data-id="${esc(s.id)}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma ronda registrada. Experimente a apresentação guiada.</div>'}
function rondas(){
 const route=session?.route??DEMO_ROUTE,active=session?.status==='active',current=active?session.index:-1;
 const progress=session?session.checkpoints.filter(p=>p.completedAt).length:0;
 return pageTitle('Mapa operacional','Acompanhe os pontos planejados, áreas de verificação e eventos da ronda.',btn(ic('help')+' Como interpretar','map-help','small'))+`<div class="map-command-page"><section class="map-command-panel"><div class="map-command-top"><div><div class="eyebrow">CARTOGRAFIA E LOCALIZAÇÃO</div><h2>${ic('map')} ${esc(route.name)}</h2><p>Ruas reais quando online · pontos ilustrativos</p></div><div class="map-command-actions">${tag(active?'Ronda em andamento':'Rota de referência',active?'green':'neutral')}${btn(ic('crosshair')+' Enquadrar rota','center-maps','small')}</div></div><div class="map-command-map"><div id="ops-map" class="map-container large"></div><div class="map-command-topbadge">${ic('pin')} ${route.points.length} pontos · raio de 25 m</div></div>${legend()}<div class="map-command-disclosure">${ic('help')} <span>O mapa mostra ruas reais, mas a linha entre os pontos é apenas ilustrativa. Não representa um caminho calculado pelas vias. A precisão do GPS pode variar.</span></div></section><aside class="map-checkpoint-panel"><div class="map-checkpoint-heading"><div class="eyebrow">SEQUÊNCIA DE VERIFICAÇÃO</div><h2>Pontos da rota</h2><p>${progress} de ${route.points.length} verificados neste cenário</p></div><div class="map-point-list">${route.points.map((p,i)=>{const done=!!session?.checkpoints[i]?.completedAt,now=active&&current===i;return `<button type="button" class="map-point-row ${done?'is-done':now?'is-current':''}" data-action="focus-route-point" data-index="${i}" aria-label="Localizar ponto ${i+1}: ${esc(p.name)}"><span class="map-point-number">${done?ic('check'):i+1}</span><span class="map-point-info"><strong>${esc(p.name)}</strong><small>${done?'Verificado':now?'Ponto obrigatório atual':'Aguardando sequência'} · 25 m</small></span><span class="map-point-target">${ic('crosshair')}</span></button>`}).join('')}</div><div class="map-point-note">${ic('clock')} Permanência de 30 segundos contínuos dentro do raio, conforme GPS confiável.</div><div class="map-point-note">${ic('shield')} Falhas ou baixa precisão do GPS exigem verificação, não representam desvio automaticamente.</div></aside></div><section class="card map-history" style="margin-top:15px"><div class="card-title"><div><h2>Histórico de rondas</h2><p>Registros guardados somente neste navegador.</p></div>${tag(`${sessions.length} rondas`,'neutral')}</div>${tablePatrols(sessionList())}</section>`;
}
function notificationRow(n){const isAlert=n.kind==='deviation';return `<button class="event-item ${!n.seenAt?'unread':''}" data-action="notification-detail" data-id="${esc(n.id)}" data-session="${esc(n.session.id)}"><span class="event-icon ${isAlert?'alert':''}">${ic(isAlert?'alert':'clipboard')}</span><span style="flex:1"><strong>${esc(n.label)}</strong><small>${esc(n.session.name)} · ${esc(n.session.route.name)}</small><p>${n.kind==='deviation'?n.justification?'Justificativa registrada, consultar o evento.':'Aguardando justificativa do colaborador.':'Ocorrência vinculada à ronda.'}</p></span><time>${time(n.at)}</time></button>`}
let alertFilter='pending';
function notificationsView(){
 const all=recentNotification(),pending=all.filter(n=>!n.seenAt),shown=alertFilter==='pending'?pending:all;
 return pageTitle('Central de alertas','Desvios e ocorrências com justificativas e histórico de avaliação.')+`<div class="alerts-command-page"><div class="alert-local-banner">${ic('shield')} <span><strong>Ambiente de avaliação</strong> Os avisos desta plataforma são registrados somente no navegador. Não há envio para supervisores remotos.</span></div><div class="alerts-queue-card"><div class="alerts-queue-head"><div><div class="eyebrow">FILA DE ATENÇÃO</div><h2>${pending.length} alerta(s) aguardando análise</h2><p>Selecione um evento para consultar a justificativa e registrar sua avaliação.</p></div>${tag(`${all.length} evento(s)`,'neutral')}</div><div class="alert-filter-tabs" aria-label="Filtrar alertas"><button type="button" data-action="filter-alerts" data-filter="pending" class="${alertFilter==='pending'?'selected':''}" aria-pressed="${alertFilter==='pending'}">Pendentes (${pending.length})</button><button type="button" data-action="filter-alerts" data-filter="all" class="${alertFilter==='all'?'selected':''}" aria-pressed="${alertFilter==='all'}">Todos (${all.length})</button></div><div class="alerts-queue-list">${shown.map(notificationRow).join('')||`<div class="alerts-empty">${ic('checkcircle')}<strong>${alertFilter==='pending'?'Nenhum alerta pendente':'Nenhum evento registrado'}</strong><p>${alertFilter==='pending'&&all.length?'Abra “Todos” para rever os registros já avaliados.':'Ao ocorrer um desvio ou ser registrada uma ocorrência, ela aparecerá aqui com o contexto da ronda.'}</p></div>`}</div><div class="alerts-footer">${ic('help')} <span>Um alerta é uma indicação para avaliação, não prova automática de irregularidade.</span></div></div></div>`;
}
function occurrences(){const rows=recentIncidents();return pageTitle('Ocorrências','Registros que devem ser avaliados conforme prioridade e contexto.')+`<div class="card"><div class="card-title"><h2>Registros de ocorrência</h2>${tag(`${rows.length} eventos`,'neutral')}</div>${rows.map(i=>`<button class="list-row" data-action="incident-detail" data-id="${esc(i.id)}" data-session="${esc(i.session.id)}"><span class="row-icon">${ic('alert')}</span><div><strong>${esc(i.title)}</strong><small>${esc(i.session.name)} · ${esc(i.pointName)} · ${fmt(i.at)}</small><p>${esc(i.description)}</p></div><span class="row-right">${tag(i.severity,i.severity==='Alta'?'red':'orange')}</span></button>`).join('')||'<div class="empty">Nenhuma ocorrência. O ronda pode registrar observações durante a operação.</div>'}</div>`}
function team(){return pageTitle('Equipe','Exemplo de organização por perfis, não uma base real de colaboradores.')+`<div class="section-note">${ic('shield')}<span>Na implantação, os acessos terão autenticação e permissões verificadas no servidor. Os nomes exibidos aqui são exemplos.</span></div><div class="grid-kpis">${[['LF','Lucas Ferreira','Ronda'],['MS','Marina Souza','Supervisão'],['CM','Camila Martins','Gestão'],['AD','Administrador','Administração']].map(([i,n,p])=>`<div class="card"><div class="avatar" style="margin-bottom:14px">${i}</div><h3>${n}</h3><small>${p} · cenário fictício</small></div>`).join('')}</div>`}
function reports(){
 const all=sessionList(),notices=recentNotification(),completed=all.filter(s=>s.status==='completed').length,progress=all.reduce((sum,s)=>sum+s.checkpoints.filter(p=>p.completedAt).length,0),possible=all.reduce((sum,s)=>sum+s.route.points.length,0);
 const ratios=[{label:'Rondas concluídas',n:completed,total:all.length,color:'safe'},{label:'Pontos verificados',n:progress,total:possible,color:'blue'},{label:'Eventos analisados',n:notices.filter(n=>n.seenAt).length,total:notices.length,color:'cyan'}];
 const dates=all.map(s=>s.startedAt).filter(Number.isFinite).sort((a,b)=>a-b);
 const range=dates.length?`${new Date(dates[0]).toLocaleDateString('pt-BR')} até ${new Date(dates.at(-1)).toLocaleDateString('pt-BR')}`:'Nenhum registro neste navegador';
 return `<div class="report-page">${pageTitle('Relatório operacional','Registros e indicadores gerados exclusivamente a partir dos dados deste ambiente.',btn(ic('print')+' Imprimir / PDF','print',''))}<div class="report-context-bar"><span>${ic('clock')} ${esc(range)}</span>${tag('Dados locais, sem servidor','neutral')}</div>${kpiCards()}<div class="report-insights-grid"><section class="card report-breakdown"><div class="eyebrow">ANÁLISE DOS REGISTROS</div><h2>Visão da execução</h2><p>Percentuais calculados sobre as rondas e eventos registrados neste navegador.</p><div class="report-progress-list">${ratios.map(item=>{const pct=item.total?Math.round(item.n/item.total*100):0;return `<div class="report-progress-row"><div class="report-progress-label"><strong>${item.label}</strong><span>${item.n} de ${item.total} <b>${pct}%</b></span></div><div class="report-progress-track" role="progressbar" aria-label="${item.label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i class="${item.color}" style="width:${pct}%"></i></div></div>`}).join('')}</div><div class="report-safety-note">${ic('shield')} <span>Indicadores de demonstração. Sem homologação do GPS ou sincronização com equipe real.</span></div></section><section class="card report-events"><div class="card-title"><div><div class="eyebrow">ATIVIDADE DOCUMENTADA</div><h2>Eventos recentes</h2></div>${tag(`${notices.length} avisos`,'neutral')}</div><div class="report-events-list">${notices.slice(0,5).map(notificationRow).join('')||`<div class="reports-empty">${ic('clipboard')}<strong>Nenhum evento registrado</strong><p>Desvios e ocorrências aparecerão aqui com horário e contexto.</p></div>`}</div></section></div><section class="card report-roster"><div class="card-title"><div><div class="eyebrow">HISTÓRICO</div><h2>Rondas registradas</h2></div>${tag(`${all.length} rondas`,'neutral')}</div>${tablePatrols(all)}</section><div class="report-note">${ic('help')} <span>Use “Imprimir / PDF” para salvar uma cópia local. O navegador realiza a impressão; nenhum documento é enviado automaticamente.</span></div></div>`;
}
function settings(){return pageTitle('Configurações da demonstração','Parâmetros observáveis e limites para uma implantação segura.')+`<div class="grid-two"><div class="card"><h2>Regras operacionais</h2>${[['Raio de validação','25 metros'],['Permanência por ponto','30 segundos contínuos'],['Sequência','Obrigatória'],['Desvio','Bloqueia avanço e solicita justificativa'],['Falha de GPS','Suspende verificação sem presumir culpa'],['Registro atual','Armazenamento neste navegador'],['Segundo plano','Android nativo: serviço com notificação; web: não suportado'],['Permissão inicial','Ciência registrada separadamente do GPS']].map(([a,b])=>`<div class="detail-pair"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><div class="card"><h2>Dados da demonstração</h2><p style="margin:12px 0">Os registros foram criados localmente. Apagar não afeta outros dispositivos ou servidores.</p>${btn(ic('refresh')+' Apagar dados locais','clear-prompt','danger full')}<p class="map-caption">Autenticação, sincronização, mapas licenciados para uso operacional e notificações reais fazem parte de implantação futura.</p></div></div>`}
function personalRecords(){const mine=sessionList().filter(s=>s.name===user.name);return pageTitle('Meus registros','Consulte suas rondas, horários e justificativas.')+`<div class="card">${tablePatrols(mine)}</div>`}
function legend(){return `<div class="map-legend maxvel-map-legend" aria-label="Legenda operacional do mapa"><span><i class="legend-dot base"></i>Base</span><span><i class="legend-dot"></i>Ponto planejado</span><span><i class="legend-dot done"></i>Concluído</span><span><i class="legend-dot radius"></i>Raio de 25 m</span><span><i class="legend-line planned"></i>Traçado ilustrativo</span><span><i class="legend-line traced"></i>Posição percorrida</span></div>`}
const latestDeviation=()=>session?.deviations.at(-1)??null;
function coach(){if(!session)return {n:1,title:'Inicie a ronda',detail:'Clique em “Iniciar ronda”. Antes de começar, leia e aceite as orientações.',benefit:'Processo iniciado com regras explícitas.'};if(session.status==='completed')return {n:7,title:'Ronda concluída',detail:'Abra o histórico para consultar horários e eventos registrados.',benefit:'Sequência e retorno documentados.'};if(movement)return {n:2,title:'Acompanhe o deslocamento',detail:'O marcador percorre posições intermediárias sobre o mapa real. Aguarde chegar ao destino.',benefit:'Acompanhamento visual da rota fictícia.'};const d=latestDeviation();if(d&&!d.justification)return {n:4,title:'Justificativa pendente',detail:'No celular, clique em “Escrever justificativa”. O avanço continua bloqueado.',benefit:'A supervisão consulta o desvio e a explicação.'};if(d&&!d.returnedAt)return {n:5,title:'Retorne ao ponto obrigatório',detail:'Justificar não conclui o ponto. Use “Deslocar até o ponto” para retornar e cumprir a permanência.',benefit:'A sequência de verificações permanece obrigatória.'};const p=currentCheckpoint(session);if(!p)return {n:6,title:'Retorne à base',detail:'Use “Retornar à base” e depois finalize a ronda.',benefit:'A operação se encerra na base prevista.'};if(session.insideSince===null)return {n:2,title:`Desloque-se até o ponto ${session.index+1}`,detail:'O botão de deslocamento simula o percurso. A contagem começará ao entrar no raio de 25 m.',benefit:'Só o ponto atual pode ser validado.'};if(!canCompletePoint(session))return {n:3,title:'Permaneça no raio',detail:`Aguarde ${Math.max(0,Math.ceil((DWELL_MS-session.checkpoints[session.index].dwellMs)/1000))} s. Se sair, a contagem reinicia.`,benefit:'A permanência tem duração verificável.'};return {n:3,title:'Confirme este ponto',detail:'Toque em “Concluir ponto e seguir”. Somente então o próximo ponto ficará disponível.',benefit:'Progressão condicionada à validação.'};}
function coachHtml(){const c=coach();return `<aside class="guide-inline" aria-label="Ajuda da etapa atual"><span class="stepnum">${String(c.n).padStart(2,'0')}</span><div style="flex:1"><strong data-live="coach-title">${esc(c.title)}</strong><p data-live="coach-detail">${esc(c.detail)}</p></div><button data-action="guide">Ajuda</button></aside>`}
function phoneTelemetry(){
 const s=session,point=s?.status==='active'?currentCheckpoint(s):null;
 const pct=s?progressPercent(s):0;
 const fix=locationFix;
 const state=s?.status==='completed'?'Concluída':s?.status==='active'?hasBlock(s)?'Atenção necessária':movement?'Em deslocamento':point?'Ronda ativa':'Retorno à base':'Pronta para iniciar';
 const stateClass=s?.status==='completed'?'finished':hasBlock(s??{deviations:[]})?'warning':'active';
 return `<div class="mobile-operational-strip"><div class="mobile-location-status"><span class="ops-live-dot"></span><div><strong>${esc(state)}</strong><small>${mode==='simulation'?'Cenário ilustrativo · sem GPS real':'GPS do dispositivo · sujeito à precisão'}</small></div></div><div class="mobile-progress-chip">${s?`${s.index}/${s.route.points.length}`:'0/4'} <span>pontos</span></div></div><div class="mobile-tracking-meta"><div>${ic('map')} <strong>${point?esc(point.name):s?.status==='completed'?'Ronda finalizada':'Rota Centro · Perímetro'}</strong></div><div class="mobile-mini-meter" role="progressbar" aria-label="Progresso da ronda" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><span style="width:${pct}%"></span></div><small>${point?'Próximo ponto obrigatório':'Verifique a sequência no mapa'} · ${mode==='real'&&fix?`Precisão ${Math.round(fix.accuracy??0)} m`:'25 m de raio por ponto'}</small></div>`;
}
function readyStartPanel(){
 return `<div class="patrol-stage-intro"><span class="patrol-stage-index">01 · PREPARAÇÃO</span><h2>Pronto para iniciar?</h2><p>Ronda em quatro pontos. Raio de 25 metros e 30 segundos de permanência por ponto.</p></div><div class="patrol-mode-toggle" aria-label="Modo da ronda"><button type="button" class="${mode==='simulation'?'selected':''}" data-action="mode-simulation" aria-pressed="${mode==='simulation'}">${ic('play')} Cenário</button><button type="button" class="${mode==='real'?'selected':''}" data-action="mode-real" ${presentation?'disabled':''} aria-pressed="${mode==='real'}">${ic('crosshair')} GPS real</button></div>${btn('Iniciar ronda '+ic('arrow'),'start','primary full')}<p class="patrol-microtext">${presentation?'Você experimenta o próprio aplicativo, com mapa e alertas ilustrativos.':mode==='real'?'O aparelho solicitará permissão para localização durante a ronda.':'O mapa contém ruas reais; trajeto e posições do cenário são simulados.'}</p>`;
}
function patrolActionContent(){
 const s=session,active=s?.status==='active',complete=s?.status==='completed',route=s?.route??DEMO_ROUTE;
 const p=active?currentCheckpoint(s):null,dev=active?latestDeviation():null,blocked=active&&hasBlock(s);
 if(!s)return readyStartPanel();
 if(complete)return `<div class="patrol-stage-intro"><span class="patrol-stage-index">RONDA FINALIZADA</span><h2>${ic('checkcircle')} Todos os pontos concluídos</h2><p>Os eventos e o retorno à base estão disponíveis no histórico deste navegador.</p></div>${btn('Consultar histórico '+ic('arrow'),'my-records','primary full')}${btn('Nova ronda','new-session','full')}`;
 if(blocked&&dev&&!dev.justification)return `<div class="patrol-stage-intro is-alert"><span class="patrol-stage-index">${ic('alert')} ATENÇÃO · AVANÇO BLOQUEADO</span><h2>Justificativa necessária</h2><p>Foi registrada uma saída da rota. Explique o motivo à supervisão, depois volte ao ponto obrigatório.</p></div>${btn('Escrever justificativa '+ic('arrow'),'justify','primary full')}<p class="patrol-microtext">Esta explicação aparece na supervisão do cenário, não é enviada remotamente.</p>`;
 if(blocked&&dev&&!dev.returnedAt)return `<div class="patrol-stage-intro is-alert"><span class="patrol-stage-index">${ic('alert')} DESVIO REGISTRADO</span><h2>Retorne ao ponto</h2><p>Justificativa registrada. Para seguir, volte ao ponto ${s.index+1} e cumpra novamente os 30 segundos.</p></div>${mode==='simulation'?btn('Simular retorno ao ponto '+ic('arrow'),'demo-arrive','primary full',movement?'disabled':''):`<div class="section-note">${ic('crosshair')} Aguarde a confirmação de GPS no local.</div>`}`;
 if(p){
  const secs=Math.floor(s.checkpoints[s.index].dwellMs/1000),ready=canCompletePoint(s);
  return `<div class="patrol-stage-intro"><span class="patrol-stage-index">PONTO ${s.index+1} / ${route.points.length}</span><h2>${esc(p.name)}</h2><p>${esc(p.instruction)}</p></div><div class="patrol-dwell"><div class="timer-ring" data-live="ring" style="--deg:${Math.min(360,secs/30*360)}deg"><span><b data-live="seconds">${secs}</b><small>/ 30 s</small></span></div><div class="patrol-dwell-info"><strong>Validação por localização</strong><div class="patrol-dwell-tags"><span data-live="req-radius" class="requirement ${s.insideSince!==null?'ok':''}">${ic('crosshair')} Dentro de 25 m</span><span data-live="req-time" class="requirement ${secs>=30?'ok':''}">${ic('clock')} Permanência</span></div><p data-live="status">${s.insideSince!==null?'Permaneça no raio até cumprir os 30 segundos.':'Dirija-se ao ponto indicado no mapa.'}</p></div></div>${btn('Concluir ponto e seguir '+ic('arrow'),'complete-point','primary full',ready?'':'disabled')}`;
 }
 return `<div class="patrol-stage-intro"><span class="patrol-stage-index">TODOS OS PONTOS VERIFICADOS</span><h2>Retorne à base</h2><p>A ronda só termina após o retorno ser confirmado pela localização.</p></div>${btn('Finalizar ronda '+ic('check'),'finish','primary full',s.returnConfirmed&&!hasBlock(s)?'':'disabled')}`;
}
function patrolScenarioControls(){
 if(!session||session.status!=='active'||mode!=='simulation')return '';
 const p=currentCheckpoint(session),busy=!!movement;
 return `<div class="patrol-scenario-tools"><div class="patrol-tools-heading"><span>${ic('play')} Comandos do cenário</span><small>Deslocamento animado</small></div><div class="patrol-quick-actions">${btn(p?'Ir ao próximo ponto':'Voltar à base','demo-arrive','',busy?'disabled':'')}${btn('Sair da rota','demo-leave','',busy?'disabled':'')}${btn('Ocorrência','incident-form','')}</div></div>`;
}
function phoneContent(){
 const s=session,route=s?.route??DEMO_ROUTE,active=s?.status==='active',point=active?currentCheckpoint(s):null,progress=s?progressPercent(s):0;
 return `<div class="patrol-workspace"><div class="patrol-statusline">${phoneTelemetry()}</div><section class="patrol-actions" aria-label="Ação atual da ronda"><div class="patrol-action-heading"><span>${ic('compass')} PRÓXIMA AÇÃO</span>${tag(presentation?'Cenário interativo':mode==='real'?'GPS real':'Simulação','neutral')}</div><div class="patrol-action-body">${patrolActionContent()}${patrolScenarioControls()}<details class="patrol-help-details"><summary>${ic('help')} Instruções e sequência da ronda</summary>${coachHtml()}<div class="patrol-point-list">${route.points.map((p,i)=>`<button type="button" data-action="point-details" data-index="${i}" class="${s?.checkpoints[i]?.completedAt?'done':active&&s.index===i?'current':''}"><b>${s?.checkpoints[i]?.completedAt?ic('check'):i+1}</b><span>${esc(p.name)}</span></button>`).join('')}</div><button type="button" class="patrol-help-link" data-action="guide">${ic('help')} Abrir guia completo</button>${active&&mode==='simulation'&&point&&s.index<route.points.length-1?btn('Testar tentativa de pular ponto','demo-skip','small'):''}</details></div></section><section class="patrol-map-panel" aria-label="Mapa da ronda"><header class="patrol-map-heading"><div><strong>${esc(route.name)}</strong><small>${esc(route.unit)} · ${s?Math.floor(progress)+'% verificado':'4 pontos planejados'}</small></div><button type="button" data-action="center-maps" title="Enquadrar rota" aria-label="Enquadrar rota e pontos">${ic('crosshair')}</button></header><div class="patrol-map-canvas"><div id="mobile-map" class="map-container mini"></div><span class="patrol-map-note">${ic('map')} Ruas reais · linha ilustrativa</span></div><div class="patrol-map-footer"><span>${ic('crosshair')} ${mode==='real'?'Posição GPS do aparelho':'Posição simulada'}</span><span data-live="coords">${locationFix?`${locationFix.lat.toFixed(5)}, ${locationFix.lng.toFixed(5)}`:'Aguardando início'}</span></div></section></div>`;
}
function phoneMockup(){return `<div class="phone-frame"><div class="phone-notch"></div><div class="phone-screen"><div class="mobile-top"><div class="side-head">${brand()}<span class="avatar" style="width:30px;height:30px;font-size:11px">${esc((session?.name??presentationName).slice(0,1))}</span></div><small>Minha ronda · ${esc(session?.name??presentationName)}</small></div><div class="phone-section">${phoneContent()}</div><nav class="mobile-nav" aria-label="Menu ilustrativo no celular"><button class="active" data-action="no-op">${ic('compass')}<span>Minha ronda</span></button><button data-action="records">${ic('folder')}<span>Registros</span></button><button data-action="incident-form" ${!session?.status||session?.status!=='active'?'disabled':''}>${ic('alert')}<span>Ocorrência</span></button></nav><div class="phone-footer">Desenvolvido por Horizon</div></div></div>`}
function supervisorCheckpointTimeline(){
 const route=session?.route??DEMO_ROUTE;
 return `<section class="card supervisor-checkpoints"><div class="card-title"><div><div class="eyebrow">SEQUÊNCIA OPERACIONAL</div><h2>${ic('pin')} Pontos de verificação</h2><p>Etapas que o ronda deve concluir em ordem</p></div>${tag(`${route.points.length} pontos`,'neutral')}</div><div class="supervisor-points">${route.points.map((point,i)=>{
  const record=session?.checkpoints?.[i];
  const done=!!record?.completedAt;
  const active=!!session&&session.status==='active'&&session.index===i;
  const state=done?'Concluído':active?'Ponto atual':'Planejado';
  return `<div class="supervisor-point ${done?'done':active?'in-progress':''}"><span class="supervisor-point-num">${done?ic('check'):i+1}</span><div><strong>${esc(point.name)}</strong><small>${done?`Verificado às ${time(record.completedAt)}`:state}</small></div><span class="supervisor-point-state">${state}</span></div>`;
 }).join('')}</div><div class="supervisor-points-note">${ic('clock')} Validação: até 25 m do ponto e permanência contínua de 30 s.</div></section>`;
}
function supervisorPanel(){const n=recentNotification().filter(x=>!session||x.session.id===session.id),point=session&&currentCheckpoint(session);return `<section class="card"><div class="supervision-header"><div><strong>${ic('eye')} Central de supervisão</strong><small>Rondas, permanência e alertas em uma só visão</small></div>${tag('Recebimento simulado','neutral')}</div><div class="compact-stats" style="margin-top:16px"><div class="compact-stat"><small>Ponto em execução</small><strong data-live="sup-point">${session?point?`${session.index+1} de ${session.route.points.length}`:'Retorno': 'Aguardando'}</strong></div><div class="compact-stat"><small>Permanência</small><strong data-live="sup-dwell">${session&&point?Math.floor(session.checkpoints[session.index].dwellMs/1000):0} / 30 s</strong></div><div class="compact-stat"><small>Situação</small><strong data-live="sup-status">${session?hasBlock(session)?'Bloqueado':session.status==='completed'?'Concluída':movement?'Em trânsito':'Em execução':'Não iniciada'}</strong></div></div><div id="supervisor-map" class="map-container"></div>${legend()}<p class="map-caption">OpenStreetMap quando online. Traçado, raio e posicionamento do colaborador são simulados.</p></section>${supervisorCheckpointTimeline()}<section class="card"><div class="card-title"><div><h2>${ic('bell')} Notificações e justificativas</h2><p>Abra um aviso para acompanhar evento e providências.</p></div>${tag(`${n.length} eventos`,'neutral')}</div><div class="event-feed" data-live="supervisor-notifications">${n.map(notificationRow).join('')||'<div class="empty">Nenhum alerta. Experimente “Simular saída da rota” ou “Registrar ocorrência”.</div>'}</div></section>`}
function controlBar(){const active=session?.status==='active',point=active&&currentCheckpoint(session);return `<section class="card presentation-control"><div class="side-head"><strong>${ic('play')} Controle da demonstração</strong>${tag('Modo simulação','neutral')}</div><p style="font-size:12px">Use estes comandos para apresentar uma ronda e observar o efeito no celular e na supervisão.</p><div class="control-row">${!session?btn('1 · Iniciar ronda','start','primary'):active?`${btn(point?`Deslocar até o ponto ${session.index+1}`:'Retornar à base','demo-arrive','primary',movement?'disabled':'')}${btn('Simular saída da rota','demo-leave','',movement?'disabled':'')}${point&&session.index<session.route.points.length-1?btn('Tentar pular ponto','demo-skip','',movement?'disabled':''):''}${btn('Registrar ocorrência','incident-form','')}`:btn('Nova simulação','new-session','primary')}</div></section>`}
function presentationShell(){const c=coach();return `<div class="presentation"><header class="app-header">${brand()}<div class="header-actions">${tag('Ambiente de avaliação','neutral')}<button class="help-toggle" data-action="guide" aria-label="Abrir ajuda e instruções">${ic('help')} Guia</button>${btn('Encerrar','end-presentation','small')}</div></header><main id="main" class="presentation-main"><div class="presentation-title"><div><div class="eyebrow">EXPERIÊNCIA OPERACIONAL · CELULAR E WEB</div><h1>O ronda executa.<br><span>A supervisão acompanha.</span></h1><p>Percorra a mesma jornada vista pelo colaborador e pela supervisão. O painel responde aos eventos da ronda em tempo real dentro deste cenário.</p></div>${tag('Cenário ilustrativo','neutral')}</div>${controlBar()}<aside class="card commercial-coach" aria-label="Orientação para a apresentação"><div class="side-head"><div><div class="eyebrow">ETAPA ${String(c.n).padStart(2,'0')} · O QUE FAZER AGORA</div><strong data-live="guide-title">${esc(c.title)}</strong></div>${btn(ic('help')+' Guia completo','guide','small')}</div><p data-live="guide-desc">${esc(c.detail)}</p><div class="coach-footer" data-live="guide-benefit"><b>O que isso demonstra:</b> ${esc(c.benefit)}</div></aside><div class="preview-layout"><section><div class="side-head" style="padding:0 7px"><strong>${ic('compass')} Experiência do ronda</strong><small>Celular · funcional</small></div>${phoneMockup()}</section><section><div class="side-head" style="padding:0 7px"><strong>${ic('chart')} Visão da supervisão</strong><small>Computador · funcional</small></div><div class="supervision-stack">${supervisorPanel()}<div class="section-note">${ic('shield')}<span><b>Proposta de valor:</b> sequência verificável, registro dos eventos e contexto para tomada de decisão. Resultados operacionais reais dependem de piloto.</span></div></div></section></div><footer class="hero-foot" style="margin-top:28px"><span>Operação, alertas e dados simulados · Desenvolvido por Horizon | Daniel N. Xavier</span><span>Não há servidor operacional conectado.</span></footer></main></div>`}
const lessonNames=['O que você verá','Início e percurso','Desvios e justificativa','Supervisão e resultado','Limites e implantação'];
function lesson(i){const stages=[`<p>Você acompanhará a mesma ronda em duas telas. O lado esquerdo orienta o colaborador; o direito recebe os eventos simulados para a supervisão.</p><ol><li>Inicie a ronda e veja a localização no mapa.</li><li>Percorra os pontos na ordem e aguarde os 30 segundos.</li><li>Simule um desvio ou registre uma ocorrência.</li><li>Consulte a notificação e a justificativa no painel.</li></ol>`,`<p>O deslocamento usa posições intermediárias sobre a cartografia real, mas o trajeto de exemplo não é uma rota de trânsito oficial.</p><ol><li>Clique em <strong>Iniciar ronda</strong> e aceite as regras.</li><li>Clique em <strong>Deslocar até o ponto 1</strong>.</li><li>Aguarde a chegada dentro do raio de 25 m.</li><li>Espere 30 segundos reais e confirme a conclusão para liberar o próximo.</li></ol>`,`<p>A progressão para quando a posição sai do corredor da rota simulada ou tenta avançar fora da sequência.</p><ol><li>Use <strong>Simular saída da rota</strong>.</li><li>O ronda verá a solicitação de justificativa.</li><li>Escreva o motivo e confirme o envio local simulado.</li><li>Volte ao ponto pendente e cumpra 30 segundos novamente: justificar não substitui a visita.</li></ol>`,`<p>No painel, os avisos reúnem nome, rota, ponto, horário, posição ilustrativa e explicação. O supervisor pode abrir o aviso e marcá-lo como analisado.</p><p style="margin-top:12px"><strong>Benefício proposto:</strong> facilitar conferências, histórico e tratamento de exceções. A eficiência só pode ser medida numa operação piloto.</p>`,`<p><strong>Protótipo, não produção.</strong> As notificações são locais, os usuários não possuem autenticação real e os registros ficam neste navegador. O mapa usa ruas reais, mas as rotas da Maxvel foram substituídas por pontos fictícios.</p><ol><li>No piloto: validar precisão GPS, rede, bateria, duração e acessibilidade.</li><li>Na implantação: servidor, autenticação, auditoria, permissões, mapas e notificações reais.</li><li>Na privacidade: documentar finalidade, acesso, retenção e tratamento conforme a LGPD.</li></ol>`];return stages[i]||stages[0]}
function showGuide(forPresentation=false,step=0){guideStage=Math.max(0,Math.min(4,step));const isLaunching=forPresentation||screen==='landing';showDialog(`<div class="eyebrow">GUIA INTERATIVO · HORIZON + MAXVEL</div><h2>Conheça o sistema sem decorar instruções.</h2><p style="font-size:12px;margin-bottom:12px">Cada tema explica o que fazer, o que observar e o valor para a empresa. A ajuda continuará acessível durante a operação.</p><nav class="guide-tabs" aria-label="Etapas do guia">${lessonNames.map((t,i)=>`<button type="button" data-action="guide-stage" data-stage="${i}" aria-current="${i===guideStage?'step':'false'}" class="${i===guideStage?'active':''}">${i+1} · ${t}</button>`).join('')}</nav><div class="guide-pan"><h3>${esc(lessonNames[guideStage])}</h3>${lesson(guideStage)}</div><div class="modal-actions">${guideStage>0?btn(ic('arrowleft')+' Anterior','guide-back',''):''}${guideStage<4?btn('Próximo assunto '+ic('arrow'),'guide-forward',''):''}</div>${isLaunching?`<div class="guide-pan" style="margin-top:18px"><h3>Pronto para testar?</h3><label class="field">Nome do ronda na apresentação<input id="presentation-name" maxlength="60" minlength="2" value="${esc(presentationName)}"></label>${btn('Abrir apresentação guiada '+ic('arrow'),'launch-presentation','primary full')}</div>`:btn('Voltar ao aplicativo','close-dialog','primary full')}`,true);modal.dataset.guideLaunch=isLaunching?'true':'false';}
function showDialog(html,wide=false){modal.className=wide?'wide':'';modal.innerHTML=`<button type="button" class="dialog-close" aria-label="Fechar janela" data-action="close-dialog">${ic('close')}</button>${html}`;if(!modal.open)modal.showModal();}
function privacy(){showDialog(`<div class="eyebrow">PRIVACIDADE E TRANSPARÊNCIA</div><h2>Uso responsável dos dados de ronda</h2><p>Este protótipo guarda nomes informados, horários, coordenadas simuladas ou dados de teste autorizados, desvios, justificativas e ocorrências somente no navegador atual.</p><div class="rules"><li><div><strong>Cartografia</strong><p>Quando online, os mapas carregam imagens do OpenStreetMap. Os pontos de ronda são fictícios; o provedor pode receber informações técnicas da visualização da região do mapa.</p></div></li><li><div><strong>Localização</strong><p>O modo GPS pede autorização do aparelho. No navegador, só funciona enquanto a página estiver ativa; o aplicativo nativo Android pode continuar com um serviço em primeiro plano e notificação visível, conforme permissões e condições do sistema. O serviço não sobrevive a uma parada forçada. Falhas ou imprecisões não são prova de irregularidade.</p></div></li><li><div><strong>Supervisão e alertas</strong><p>O recebimento nesta versão é simulado e local. Nenhum supervisor real recebe automaticamente avisos.</p></div></li><li><div><strong>Próximas etapas</strong><p>Antes do uso operacional: autenticação, infraestrutura, controle de acesso, segurança, política de retenção e documentação LGPD.</p></div></li></div>${btn('Entendi','close-dialog','primary full')}`,true)}
function trackingIntroduction(){
 const requirements=LOCATION_REQUIREMENTS.map((r,i)=>`<div class="consent-feature"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(r.title)}</strong><p>${esc(r.description)}</p></div></div>`).join('');
 showDialog(`<div class="consent-compact"><div class="consent-compact-head"><span class="consent-symbol">${ic('pin')}</span><div><div class="eyebrow">PRIMEIRA ABERTURA · TRANSPARÊNCIA</div><h2>Localização durante a ronda</h2></div></div><p class="consent-compact-sub">Para registrar pontos e trajetos da sua ronda, o sistema precisa acessar a localização <b>durante o serviço autorizado</b>.</p><div class="consent-compact-points"><div>${ic('checkcircle')}<span>O acompanhamento pode continuar com a tela bloqueada ou usando outros apps <b>na versão Android nativa</b>.</span></div><div>${ic('checkcircle')}<span>Uma notificação visível permite identificar e parar o acompanhamento.</span></div><div>${ic('checkcircle')}<span>O navegador não acompanha sua posição depois de fechado. O sistema não ignora uma parada forçada.</span></div></div><details class="consent-details"><summary>Ver condições completas e privacidade</summary><div class="consent-features">${requirements}</div></details><div class="consent-disclosure"><b>Importante:</b> o aceite registra que você leu as condições, mas <b>não concede permissão ao GPS</b>. Essa autorização será solicitada pelo Android ou navegador ao iniciar uma ronda real. Alertas da demonstração são locais.</div><label class="check-label consent-check"><input type="checkbox" id="location-intro-check">Li e compreendi as condições de localização durante a ronda.</label><div class="consent-actions">${btn('Li e aceito · Continuar '+ic('arrow'),'accept-location-notice','primary full','disabled')}${btn('Explorar sem localização GPS','decline-location-notice','secondary full')}</div><p class="consent-small">O acompanhamento deve ocorrer somente durante rondas autorizadas; a empresa deve definir as regras de privacidade.</p></div>`,true);
 modal.classList.add('consent-dialog');
 modal.dataset.mandatoryNotice='true';
}
function profileDialog(){
 if(!user)return;
 showDialog(`<div class="profile-modal"><div class="profile-heading"><span class="avatar">${esc(user.name.charAt(0).toUpperCase())}</span><div><div class="eyebrow">ACESSO ATUAL</div><div class="profile-name">${esc(user.name)}</div><div class="profile-meta">${esc(roleName[user.role])} · Ambiente de avaliação</div></div></div><div class="profile-actions">${btn(ic('help')+' Instruções e ajuda','guide','full')}${btn(ic('shield')+' Privacidade e dados','privacy','full')}${btn(ic('logout')+' Sair deste perfil','logout','full')}</div><p class="map-caption">Os dados desta avaliação ficam neste navegador. O acesso de produção exigirá autenticação.</p></div>`,false);
}
function loginDialog(){showDialog(`<div class="eyebrow">ACESSO À DEMONSTRAÇÃO</div><h2>Escolha sua experiência</h2><p style="font-size:12px;margin-bottom:20px">A seleção de perfil mostra as telas disponíveis. Não corresponde a um login seguro de produção.</p><form id="login-form"><label class="field">Seu nome<input name="name" placeholder="Como podemos te chamar?" required minlength="2" maxlength="60" autocomplete="name"></label><div class="choice-row">${[['ronda','Ronda','Executar pontos'],['supervisor','Supervisão','Ver equipe'],['gestor','Gestão','Ver operação'],['admin','Administração','Ver tudo']].map(([role,title,desc])=>`<label class="choice"><input type="radio" name="role" value="${role}" ${role==='ronda'?'checked':''}><span><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}</div><button type="submit" class="button primary full">Acessar minha área ${ic('arrow')}</button></form>`,true)}
function startDialog(){const real=mode==='real'&&!presentation;showDialog(`<div class="eyebrow">ORIENTAÇÕES OBRIGATÓRIAS</div><h2>Antes de iniciar a ronda</h2><ol class="rules"><li><div><strong>Siga a ordem dos pontos</strong><p>O próximo ponto é liberado somente depois do anterior.</p></div></li><li><div><strong>Entre na área delimitada</strong><p>A validação exige localização dentro do raio de 25 metros, com precisão suficiente.</p></div></li><li><div><strong>Permaneça 30 segundos contínuos</strong><p>Se sair ou perder o sinal confiável, a contagem reinicia para garantir o registro.</p></div></li><li><div><strong>Informe desvios e ocorrências</strong><p>Uma saída da rota bloqueia o avanço e pede justificativa. O supervisor recebe o contexto somente nesta simulação.</p></div></li><li><div><strong>Finalize na base</strong><p>Após os pontos, volte à base. Falhas técnicas devem ser analisadas por pessoas.</p></div></li></ol><div class="section-note">${ic('help')}<span>${real?'O aparelho pedirá permissão de localização; a versão nativa Android pode manter um serviço visível em segundo plano durante a ronda. No navegador, o GPS para ao fechar a página.':'O marcador se deslocará sobre um mapa de ruas reais; trajetos e alertas serão simulados. Os 30 segundos serão reais.'}</span></div><label class="check-label"><input type="checkbox" id="declaration-check">Li as orientações e compreendi o funcionamento da ronda.</label>${btn('Confirmar e iniciar '+ic('arrow'),'confirm-start','primary full','disabled')}`,true)}
function incidentDialog(){if(!session||session.status!=='active'){notify('Inicie uma ronda antes de registrar ocorrência.');return;}showDialog(`<div class="eyebrow">REGISTRO VINCULADO À RONDA</div><h2>Registrar ocorrência</h2><p style="font-size:12px;margin-bottom:15px">Descreva o que foi observado. A notificação será mostrada localmente na supervisão.</p><form id="incident-form"><label class="field">Título<input name="title" required minlength="3" maxlength="100" placeholder="O que aconteceu?"></label><label class="field">Descrição<textarea name="description" required minlength="10" maxlength="1400" placeholder="Informe o que você observou e o contexto."></textarea></label><label class="field">Prioridade<select name="severity"><option>Baixa</option><option selected>Média</option><option>Alta</option></select></label><label class="check-label"><input name="truth" type="checkbox" required>Confirmo que o relato corresponde ao que observei nesta simulação.</label><button type="submit" class="button primary full">Registrar ocorrência ${ic('arrow')}</button></form>`)}
function justificationDialog(){const d=latestDeviation();if(!d||d.justification)return;showDialog(`<div class="eyebrow" style="color:#b93d56">SOLICITAÇÃO DE JUSTIFICATIVA</div><h2>Informe o motivo da saída</h2><p style="font-size:12px;margin:0 0 13px">Escreva uma justificativa que enviaremos ao supervisor, pois você saiu da rota.</p><div class="detail-pair"><span>Ponto pendente</span><strong>${esc(d.pointName)}</strong></div><div class="detail-pair"><span>Horário</span><strong>${fmt(d.at)}</strong></div><form id="justification-form" style="margin-top:20px"><label class="field">Justificativa<textarea required name="reason" minlength="10" maxlength="1400" placeholder="Descreva o motivo e o que aconteceu."></textarea></label><div class="section-note">${ic('shield')}<span>O retorno ao ponto e os 30 segundos continuam obrigatórios. O recebimento pela supervisão é simulado.</span></div><button type="submit" class="button primary full" style="margin-top:14px">Enviar justificativa ${ic('arrow')}</button></form>`)}
function notificationDialog(id,sid){const s=sessions.find(x=>x.id===sid),n=s?.notifications.find(x=>x.id===id);if(!n)return;const d=s.deviations.find(x=>x.id===n.deviationId),i=s.incidents.find(x=>x.id===n.incidentId);showDialog(`<div class="eyebrow">SUPERVISÃO · EVENTO SIMULADO</div><h2>${esc(n.label)}</h2>${tag(n.seenAt?'Analisada':n.justification?'Justificativa recebida':'Pendente',n.seenAt?'green':n.justification?'neutral':'orange')}<div style="margin:17px 0">${[['Responsável',s.name],['Rota',s.route.name],['Horário',fmt(n.at)],['Ponto',d?.pointName??i?.pointName??'Não identificado'],['Posição ilustrativa',d?`${d.position.lat.toFixed(6)}, ${d.position.lng.toFixed(6)}`:'Não informada']].map(([a,b])=>`<div class="detail-pair"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div>${d?`<div class="section-note alert">${ic('alert')}<span>Desvio aproximado: ${d.distance} m do corredor de rota de demonstração. Área de validação por ponto: ${RADIUS_METERS} m.</span></div><div class="guide-pan" style="margin-top:13px"><h3>Justificativa do ronda</h3><p>${esc(d.justification||'Aguardando explicação.')}</p></div><div class="detail-pair"><span>Retorno ao ponto</span><strong>${d.returnedAt?fmt(d.returnedAt):'Pendente'}</strong></div>`:`<div class="guide-pan"><h3>Descrição da ocorrência</h3><p>${esc(i?.description)}</p></div>`}<div class="section-note">${ic('help')}<span>É um evento fictício registrado apenas nesta demonstração. Não foi encaminhado externamente.</span></div>${n.seenAt?btn('Fechar','close-dialog','primary full'):btn('Marcar como analisada','acknowledge','primary full',`data-id="${esc(n.id)}" data-session="${esc(s.id)}"`)}`,true)}
function detailSession(id){const s=sessions.find(x=>x.id===id);if(!s)return;showDialog(`<div class="eyebrow">DETALHES DE UMA RONDA</div><h2>${esc(s.route.name)}</h2>${tag(s.status==='completed'?'Concluída':'Em andamento',s.status==='completed'?'green':'orange')}<div style="margin:17px 0">${[['Colaborador',s.name],['Início',fmt(s.startedAt)],['Conclusão',fmt(s.finishedAt)],['Pontos',`${s.index} de ${s.route.points.length}`],['Desvios',s.deviations.length],['Ocorrências',s.incidents.length]].map(([a,b])=>`<div class="detail-pair"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div><h3>Histórico de eventos</h3><div class="timeline" style="margin-top:13px">${s.timeline.map(x=>`<div class="timeline-entry"><strong>${esc(x.label)}</strong><small>${fmt(x.at)}</small></div>`).join('')}</div>${btn('Fechar','close-dialog','primary full')}`,true)}
function pointDialog(index){const route=session?.route??DEMO_ROUTE,p=route.points[index];if(!p)return;const completed=session?.checkpoints[index]?.completedAt;showDialog(`<div class="eyebrow">PONTO ${index+1} · ROTA DEMONSTRATIVA</div><h2>${esc(p.name)}</h2><p>${esc(p.instruction)}</p>${tag(completed?'Concluído':session?.index===index?'Ponto atual':'Pendente',completed?'green':'neutral')}<div style="margin-top:16px">${[['Raio','25 metros'],['Permanência','30 segundos contínuos'],['Sequência',`${index+1} de ${route.points.length}`],['Localização', 'Ilustrativa no modo simulado']].map(([a,b])=>`<div class="detail-pair"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>${btn('Entendi','close-dialog','primary full')}`)}
function finishDialog(){showDialog(`<div class="eyebrow">CONFIRMAR CONCLUSÃO</div><h2>Finalizar esta ronda?</h2><p style="font-size:12px">Os quatro pontos já foram concluídos e o retorno à base foi identificado. O registro ficará salvo neste navegador.</p><div class="modal-actions">${btn('Cancelar','close-dialog')}${btn('Finalizar ronda','confirm-finish','primary')}</div>`)}
async function startSession(){const now=Date.now();if(mode==='real'&&!presentation){
 if(!navigator.geolocation){notify('Geolocalização indisponível neste navegador.');return;}
 try{const loc=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:0}));
  const f={lat:loc.coords.latitude,lng:loc.coords.longitude,accuracy:loc.coords.accuracy,at:now};
  if(f.accuracy>25){notify(`Sinal com precisão de ${Math.round(f.accuracy)} m. Tente em uma área com melhor recepção.`);return;}
  const route=offsetRouteNear(f.lat,f.lng);session=createSession(user?.name??presentationName,route,now,'real');locationFix=f;
  try{window.AndroidTracking?.startTracking()}catch{notify('Não foi possível iniciar o serviço nativo. GPS seguirá somente com app aberto.');}
  deviceWatch=navigator.geolocation.watchPosition(pos=>{const f={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy,at:Date.now()};locationFix=f;processPosition()},err=>{contextWarning='Sinal GPS indisponível. A permanência será reiniciada até obter localização confiável.';notify(contextWarning)},{enableHighAccuracy:true,maximumAge:2000,timeout:15000});
 }catch{notify('Permita o uso do GPS ou volte à simulação.');return;}
 }else{session=createSession(user?.name??presentationName,DEMO_ROUTE,now,'simulation');locationFix={...session.route.base,accuracy:5,at:now};}
 movement=null;contextWarning='';save();modal.close();render();window.scrollTo({top:0,behavior:'instant'});notify('Ronda iniciada. Siga as orientações do primeiro ponto.');
}
function stopLocation(){if(deviceWatch!=null&&navigator.geolocation){navigator.geolocation.clearWatch(deviceWatch);deviceWatch=null;}try{window.AndroidTracking?.stopTracking()}catch{}}
function travelTo(target,label){if(!session||session.status!=='active'||movement||mode!=='simulation')return;const from=locationFix??session.route.base;movement=travel(from,target,travelDuration(from,target));session.timeline.unshift({id:`move-${Date.now()}`,kind:'movement',at:Date.now(),label});save();render();notify(`${label} · posição simulada`)}
function startMove(kind){const p=currentCheckpoint(session);if(kind==='demo-arrive')travelTo(p??session.route.base,p?`Deslocamento até ${p.name}`:'Retorno à base iniciado');
 else if(kind==='demo-leave'){const place=p??session.route.base;travelTo({lat:place.lat+.00064,lng:place.lng+.00074},'Afastamento do corredor simulado');}
 else if(kind==='demo-skip'){const next=session?.route.points[session.index+1];if(next)travelTo(next,'Tentativa de pular ponto');}}
function processPosition(){if(!session||session.status!=='active'||screen==='landing')return;
 const now=Date.now(),priorDeviations=session.deviations.length,priorReturns=session.deviations.map(d=>d.returnedAt),priorValid=session.returnConfirmed;
 const result=updateLocation(session,locationFix,now);
 if(session.deviations.length>priorDeviations){save();render();window.scrollTo({top:0,behavior:'instant'});notify('Desvio detectado. Justificativa solicitada e aviso exibido na supervisão · simulação.');return;}
 if(priorReturns.some((r,i)=>!r&&session.deviations[i]?.returnedAt)){save();render();notify('Retorno registrado. A permanência de 30 segundos recomeçou.');return;}
 if(!priorValid&&session.returnConfirmed){save();render();notify('Retorno à base confirmado. Você pode concluir a ronda.');return;}
 for(const map of liveMaps)map?.update({session,position:locationFix??session.route.base});
 updateLive(result);
}
function updateLive(result){if(!session||session.status!=='active')return;const p=currentCheckpoint(session),elapsed=p?Math.floor(session.checkpoints[session.index].dwellMs/1000):0,c=coach();
 for(const el of document.querySelectorAll('[data-live="seconds"]'))el.textContent=elapsed;
 for(const el of document.querySelectorAll('[data-live="ring"]'))el.style.setProperty('--deg',`${Math.min(360,elapsed/30*360)}deg`);
 for(const el of document.querySelectorAll('[data-live="coords"]'))el.textContent=locationFix?`${locationFix.lat.toFixed(5)}, ${locationFix.lng.toFixed(5)} · precisão ${Math.round(locationFix.accuracy??5)} m`:'Sem leitura válida';
 for(const el of document.querySelectorAll('[data-live="status"]'))el.innerHTML=result?.reason==='gps-unreliable'?`${ic('crosshair')} Aguardando posição GPS confiável. O tempo foi reiniciado.`:hasBlock(session)?`${ic('alert')} Avanço bloqueado. Justifique e retorne ao ponto.`:session.insideSince!==null?elapsed>=30?`${ic('checkcircle')} Tempo cumprido. Confirme a conclusão do ponto.`:`${ic('clock')} Permaneça no raio por mais ${30-elapsed} segundos.`:`${ic('pin')} Vá ao ponto ${session.index+1}: ${esc(p?.name??'base')}.`;
 for(const el of document.querySelectorAll('[data-live="req-time"]'))el.classList.toggle('ok',elapsed>=30);
 for(const el of document.querySelectorAll('[data-live="req-radius"]'))el.classList.toggle('ok',session.insideSince!==null);
 for(const el of document.querySelectorAll('[data-action="complete-point"]'))el.disabled=!canCompletePoint(session);
 for(const el of document.querySelectorAll('[data-action="finish"]'))el.disabled=!session.returnConfirmed||hasBlock(session);
 const replacements={'guide-title':c.title,'guide-desc':c.detail,'coach-title':c.title,'coach-detail':c.detail,'sup-point':p?`${session.index+1} de ${session.route.points.length}`:'Retorno','sup-dwell':p?`${elapsed} / 30 s`:'Pontos concluídos','sup-status':hasBlock(session)?'Bloqueado':movement?'Em trânsito':session.insideSince!==null?'No ponto':'Em percurso'};
 for(const [key,value]of Object.entries(replacements))for(const el of document.querySelectorAll(`[data-live="${key}"]`))el.textContent=value;
 for(const el of document.querySelectorAll('[data-live="guide-benefit"]'))el.innerHTML=`<b>O que isso demonstra:</b> ${esc(c.benefit)}`;
}
function syncNativeHistory(){
 if(!window.AndroidTracking||!session||mode!=='real'||session.status!=='active')return;
 try{
  const last=session.lastNativeSyncAt??session.startedAt;
  const rows=JSON.parse(window.AndroidTracking.getLocationsSince(last)||'[]');
  if(!Array.isArray(rows)||!rows.length)return;
  for(const row of rows){const at=Number(row.at),lat=Number(row.lat),lng=Number(row.lng),accuracy=Number(row.accuracy);
   if(!Number.isFinite(at)||at<=last||!Number.isFinite(lat)||!Number.isFinite(lng))continue;
   const sample={lat,lng,accuracy,at};updateLocation(session,sample,at);
   session.lastNativeSyncAt=at;locationFix=sample;
  }
  save();render();notify('Posições registradas no Android foram recuperadas para a ronda.');
 }catch(err){console.warn('Histórico nativo indisponível',err)}
}
function realtimeTick(){if(!session||session.status!=='active'||document.hidden)return;
 if(mode==='simulation'){if(movement){const f=interpolated(movement);locationFix={lat:f.lat,lng:f.lng,accuracy:5,at:Date.now()};if(f.finished){movement=null;save();render();}}else if(locationFix)locationFix.at=Date.now();}
 processPosition();}
setInterval(realtimeTick,180);
setInterval(()=>{if(session?.status==='active')save()},10000);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&session?.status==='active'){if(!window.AndroidTracking){session.insideSince=null;const p=currentCheckpoint(session);if(p)session.checkpoints[session.index].dwellMs=0;}movement=null;save();}else if(screen!=='landing'&&session?.status==='active'){syncNativeHistory();render()}});
window.addEventListener('focus',()=>{if(window.AndroidTracking&&session?.status==='active'&&mode==='real')syncNativeHistory()});
async function handleAction(event){const el=event.target.closest('[data-action],[data-view]');if(!el||el.disabled)return;if(el.tagName==='A')event.preventDefault();
 const nav=el.dataset.view;if(nav){if(!user||!allNav[user.role].find(x=>x[0]===nav))return;view=nav;render();window.scrollTo({top:0,behavior:'instant'});return;}
 const act=el.dataset.action;
 if(act==='close-dialog'){if(modal.dataset.mandatoryNotice==='true')return;modal.close();return;}
 if(act==='accept-location-notice'){if(!modal.querySelector('#location-intro-check')?.checked)return;try{saveConsent()}catch{notify('Não foi possível registrar a ciência neste navegador.');return;}modal.dataset.mandatoryNotice='false';modal.close();notify('Orientações registradas. O GPS será solicitado apenas ao iniciar uma ronda real.');return;}
 if(act==='decline-location-notice'){modal.dataset.mandatoryNotice='false';modal.close();notify('Você pode explorar a simulação sem conceder localização.');return;}
 if(act==='tracking-info'){trackingIntroduction();return;}
 if(act==='no-op'){notify('Você está na tela de ronda.');return;}
 if(act==='presentation-intro'){simulationIntro();return;}
 if(act==='guide'){showGuide(false);return;}
 if(act==='guide-stage'){const input=modal.querySelector('#presentation-name');if(input?.value?.trim())presentationName=input.value.trim().slice(0,60);showGuide(modal.dataset.guideLaunch==='true',Number(el.dataset.stage));return;}
 if(act==='guide-back'||act==='guide-forward'){const input=modal.querySelector('#presentation-name');if(input?.value?.trim())presentationName=input.value.trim().slice(0,60);showGuide(modal.dataset.guideLaunch==='true',Math.max(0,Math.min(4,guideStage+(act==='guide-forward'?1:-1))));return;}
 if(act==='launch-presentation'){
  const name=modal.querySelector('#presentation-name')?.value?.trim()||presentationName;
  if(name.length<2){notify('Informe um nome com pelo menos duas letras.');return;}
  beginSimulation(name,false,'ronda');return;
 }
 if(act==='end-presentation'){endSimulation();return;}
 if(act==='launch-scenario'){
  beginSimulation('Ronda de demonstração',true,'supervisor');
  notify('Cenário ativo. Alterne para Ronda para mover o marcador e gerar eventos.');return;
 }
 if(act==='sim-role'){
  if(!presentation||!['ronda','supervisor','gestor','admin'].includes(el.dataset.role))return;
  user={name:presentationName,role:el.dataset.role};
  view=user.role==='ronda'?'minha-ronda':'overview';
  render();window.scrollTo({top:0,behavior:'instant'});return;
 }
if(act==='profile-menu'){profileDialog();return;}
 if(act==='login'){loginDialog();return;}
 if(act==='logout'&&presentation){endSimulation();return;}
 if(act==='logout'){stopLocation();user=null;session=null;mode='simulation';screen='landing';locationFix=null;movement=null;render();return;}
 if(act==='privacy'){privacy();return;}
 if(act==='start'){startDialog();return;}
 if(act==='confirm-start'){if(mode==='real'&&!presentation&&!getConsent()){trackingIntroduction();return;}await startSession();return;}
 if(act==='mode-real'||act==='mode-simulation'){if(presentation&&act==='mode-real'){notify('Neste cenário você não precisa ativar GPS.');return;}if(session?.status==='active')return;mode=act==='mode-real'?'real':'simulation';render();return;}
 if(act==='demo-arrive'||act==='demo-leave'||act==='demo-skip'){startMove(act);return;}
 if(act==='justify'){justificationDialog();return;}
 if(act==='incident-form'){incidentDialog();return;}
 if(act==='complete-point'){if(!session)return;updateLocation(session,locationFix,Date.now());if(!completePoint(session)){notify('Cumpra os 30 segundos dentro do raio e resolva qualquer desvio.');return;}save();render();notify(currentCheckpoint(session)?`Ponto concluído. Ponto ${session.index+1} liberado.`:'Pontos concluídos. Retorne à base.');return;}
 if(act==='finish'){if(!session)return;finishDialog();return;}
 if(act==='confirm-finish'){if(finishSession(session)){stopLocation();movement=null;save();render();notify('Ronda finalizada, registro salvo neste navegador.')}else notify('Conclua os pontos e retorne à base.');return;}
 if(act==='new-session'){session=null;movement=null;locationFix=null;render();return;}
 if(act==='point-details'){pointDialog(Number(el.dataset.index));return;}
 if(act==='notification-detail'){notificationDialog(el.dataset.id,el.dataset.session);return;}
 if(act==='acknowledge'){const s=sessions.find(x=>x.id===el.dataset.session);if(s&&acknowledge(s,el.dataset.id)){persist();modal.close();render();notify('Análise registrada no cenário demonstrativo.')}return;}
 if(act==='incident-detail'){const s=sessions.find(x=>x.id===el.dataset.session),i=s?.incidents.find(x=>x.id===el.dataset.id);if(i)showDialog(`<div class="eyebrow">OCORRÊNCIA DE DEMONSTRAÇÃO</div><h2>${esc(i.title)}</h2>${tag(i.severity,'orange')}<div style="margin:16px 0"><div class="detail-pair"><span>Ronda</span><strong>${esc(s.name)}</strong></div><div class="detail-pair"><span>Ponto</span><strong>${esc(i.pointName)}</strong></div><div class="detail-pair"><span>Horário</span><strong>${fmt(i.at)}</strong></div></div><p>${esc(i.description)}</p>${btn('Fechar','close-dialog','primary full')}`);return;}
 if(act==='session-detail'){detailSession(el.dataset.id);return;}
 if(act==='nav-rondas'){view='rondas';render();return;}
 if(act==='my-records'||act==='records'){if(presentation&&session){detailSession(session.id);return;}view='registros';render();return;}
 if(act==='map-help'){showDialog(`<div class="eyebrow">COMO LER O MAPA</div><h2>Localização e pontos de ronda</h2><div class="map-help-list"><p><strong>Mapa de ruas:</strong> base cartográfica OpenStreetMap, com alternativa esquemática se ficar offline.</p><p><strong>Linha tracejada:</strong> ligação ilustrativa entre pontos. Não é uma rota calculada pelas ruas.</p><p><strong>Linha contínua ciano:</strong> posições observadas enquanto a tela está ativa na simulação.</p><p><strong>Círculo ao redor do ponto:</strong> área de validação de 25 m. É necessário permanecer 30 s seguidos, com localização confiável.</p><p><strong>Marcador vermelho:</strong> ponto de evento de desvio registrado para análise. GPS impreciso, por si só, não implica irregularidade.</p></div>${btn('Entendi','close-dialog','primary full')}`);return;}
 if(act==='focus-route-point'){const idx=Number(el.dataset.index);if(!Number.isInteger(idx)||idx<0||idx>=(session?.route??DEMO_ROUTE).points.length)return;const map=liveMaps.find(m=>m.container?.id==='ops-map');if(!map?.focusPoint(idx))pointDialog(idx);return;}
 if(act==='filter-alerts'){const filter=el.dataset.filter;if(filter!=='pending'&&filter!=='all')return;alertFilter=filter;render();return;}
 if(act==='center-maps'){liveMaps.forEach(m=>m.fit());return;}
 if(act==='print'){window.print();return;}
 if(act==='clear-prompt'){showDialog(`<h2>Apagar os dados deste navegador?</h2><p>As rondas, justificativas, ocorrências e notificações locais da demonstração serão apagadas.</p><div class="modal-actions">${btn('Cancelar','close-dialog')}${btn('Apagar dados','confirm-clear','danger')}</div>`);return;}
 if(act==='confirm-clear'){clearState();sessions=[];session=null;stopLocation();movement=null;locationFix=null;render();notify('Dados locais apagados.');return;}
}
document.addEventListener('click',e=>{handleAction(e).catch(err=>{console.error(err);notify('Não foi possível concluir. Tente novamente.');})});
modal.addEventListener('change',e=>{if(e.target.id==='declaration-check'){const el=modal.querySelector('[data-action="confirm-start"]');if(el)el.disabled=!e.target.checked}if(e.target.id==='location-intro-check'){const b=modal.querySelector('[data-action="accept-location-notice"]');if(b)b.disabled=!e.target.checked}});
modal.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);
 if(e.target.id==='login-form'){const name=String(f.get('name')||'').trim(),role=f.get('role');if(name.length<2||!allNav[role]){notify('Informe nome e perfil válidos.');return;}user={name,role};view=role==='ronda'?'minha-ronda':'overview';screen='dashboard';presentation=false;session=null;mode='simulation';modal.close();render();notify('Acesso demonstrativo iniciado. Abra Ajuda a qualquer momento.');return;}
 if(e.target.id==='justification-form'){if(!session)return;const d=latestDeviation();if(!justifyDeviation(session,d?.id,String(f.get('reason')||''))){notify('Informe ao menos 10 caracteres na justificativa.');return;}save();modal.close();render();notify('Justificativa recebida pela supervisão · simulação local.');return;}
 if(e.target.id==='incident-form'){if(!session)return;const i=registerIncident(session,{title:f.get('title'),description:f.get('description'),severity:f.get('severity')});if(!i){notify('Preencha título e descrição com detalhes suficientes.');return;}save();modal.close();render();notify('Ocorrência registrada e exibida na supervisão · simulação local.');return;}
});
window.addEventListener('online',()=>{if(screen!=='landing'&&!modal.open)notify('Conexão restabelecida. O mapa pode voltar a carregar.');});
window.addEventListener('offline',()=>notify('Sem internet: o esquema alternativo mantém a rota visível.'));
modal.addEventListener('cancel',e=>{if(modal.dataset.mandatoryNotice==='true')e.preventDefault()});
// Recuperação local: somente da ronda real ainda ativa; dados de demonstração não implicam login seguro.
if(persisted?.activeSessionId&&persisted.activeUser){
 const recovered=sessions.find(x=>x.id===persisted.activeSessionId&&x.status==='active'&&x.mode==='real');
 if(recovered){session=recovered;user=persisted.activeUser;mode='real';screen='dashboard';view='minha-ronda';contextWarning='Verificando histórico de localização após retomar.';}
}
render();
if(!getConsent())trackingIntroduction();
else if(window.AndroidTracking&&session?.status==='active')setTimeout(syncNativeHistory,300);
